const f = $('Receive Payment Change Request').first().json;
const p = $('Set Fraud Policy').first().json;
const reg = $input.all().map(i => i.json).filter(r => r && (r.vendor_domain || r.vendor_name));
const clip = (s, n) => String(s == null ? '' : s).slice(0, n);
const low = v => clip(v, 2000).trim().toLowerCase();
const addr = e => { const s = low(e).replace(/"/g,''); const lt = s.lastIndexOf('<'); const gt = s.lastIndexOf('>'); const inner = (lt >= 0 && gt > lt) ? s.slice(lt+1, gt) : s; return inner.replace(/[<>]/g,'').trim(); };
const safeAddr = a => a.replace(/[^a-z0-9._%+\-@]/g,'').slice(0, 320);
const safeDom = d => d.replace(/[^a-z0-9.\-]/g,'').slice(0, 253);
const dom = e => { const a = addr(e); const i = a.lastIndexOf('@'); return safeDom(i >= 0 ? a.slice(i+1).trim() : a); };
const HOMO = {'0':'o','1':'l','3':'e','4':'a','5':'s','7':'t','8':'b','2':'z'};
const deHomo = s => Array.from(s).map(c => HOMO[c] || c).join('');
const strip = d => deHomo(low(d)).replace(/[^a-z0-9.]/g,'').slice(0, 253);
const acct = v => clip(v, 64).toUpperCase().replace(/[^A-Z0-9]/g,'');
const looksIban = a => /^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$/.test(a);
function lev(a,b){const m=a.length,n=b.length;const d=[];for(let i=0;i<=m;i++){d[i]=[i];}for(let j=0;j<=n;j++){d[0][j]=j;}for(let i=1;i<=m;i++){for(let j=1;j<=n;j++){d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));}}return d[m][n];}
function ibanOk(s){if(s.length<15||s.length>34){return false;}const r=s.slice(4)+s.slice(0,4);let t=0;for(const ch of r){const v=/[0-9]/.test(ch)?ch:String(ch.charCodeAt(0)-55);for(const dg of v){t=(t*10+Number(dg))%97;}}return t===1;}
const fromAddr = safeAddr(addr(f.from_address));
const replyTo = f.reply_to ? safeAddr(addr(f.reply_to)) : '';
const fromDom = dom(f.from_address);
const replyDom = replyTo ? dom(f.reply_to) : '';
const claimed = acct(f.claimed_iban);
const vendorName = low(f.vendor_name).slice(0, 200);
const fd = strip(fromDom);
let exact = null; let sub = null; let best = 99; let nearest = null;
for(const r of reg){ const vd = strip(r.vendor_domain); if(!vd || !fd){ continue; } if(vd === fd){ exact = r; best = 0; nearest = r; break; } if(fd.endsWith('.' + vd)){ if(!sub){ sub = r; } continue; } const dist = lev(vd, fd); if(dist < best){ best = dist; nearest = r; } }
let named = null;
if(!exact && !sub && vendorName){ for(const r of reg){ if(low(r.vendor_name) && low(r.vendor_name) === vendorName){ named = r; break; } } }
const isLookalike = (!exact && !sub && nearest && best >= 1 && best <= p.lookalike_max_distance);
const ref = exact || sub || named || (isLookalike ? nearest : null);
const signals = [];
let score = 0;
const add = (w, code, detail) => { score = score + w; signals.push({ weight: w, code: code, detail: detail }); };
if(sub){ add(5,'SUBDOMAIN_SENDER','Sender domain ' + fromDom + ' is a subdomain of the registered vendor domain ' + sub.vendor_domain); }
else if(isLookalike){ add(35,'LOOKALIKE_DOMAIN','Sender domain ' + fromDom + ' is ' + best + ' character(s) away from the registered vendor domain ' + nearest.vendor_domain); }
else if(!exact){ add(20,'UNKNOWN_DOMAIN','Sender domain ' + (fromDom || 'not supplied') + ' does not match any vendor domain in the register'); }
if(replyDom && replyDom !== fromDom){ add(25,'REPLY_TO_MISMATCH','Reply-To domain ' + replyDom + ' differs from the From domain ' + fromDom); }
if(ref && ref.authorised_emails){ const allowed = low(ref.authorised_emails).split(',').map(s => s.trim()).filter(Boolean); if(allowed.length && allowed.indexOf(fromAddr) === -1){ add(15,'UNAUTHORISED_SENDER',fromAddr + ' is not an authorised billing contact for ' + ref.vendor_name); } }
if(claimed){
  if(looksIban(claimed) && !ibanOk(claimed)){ add(30,'IBAN_CHECKSUM_FAIL','The account is formatted as an IBAN but fails the ISO 13616 mod-97 checksum, so it cannot be a real IBAN'); }
  if(ref && ref.known_iban){
    const known = acct(ref.known_iban);
    if(known && known !== claimed){
      add(40,'BANK_DETAILS_CHANGED','The requested account does not match the verified account on file for ' + ref.vendor_name);
      if(looksIban(known) && looksIban(claimed) && known.slice(0,2) !== claimed.slice(0,2)){ add(20,'COUNTRY_HOP','Account country changed from ' + known.slice(0,2) + ' to ' + claimed.slice(0,2)); }
    }
  }
}
else { add(10,'NO_ACCOUNT_SUPPLIED','No account number was supplied, so the change cannot be verified against the register'); }
if(!ref){ add(10,'VENDOR_NOT_IN_REGISTER','This sender could not be matched to any vendor in the register, so there is no verified account or callback number to check against'); }
return [{ json: { vendor_matched: ref ? ref.vendor_name : null, callback_phone: ref ? ref.callback_phone : null, known_iban_last4: ref && ref.known_iban ? String(ref.known_iban).slice(-4) : null, from_address: fromAddr, from_domain: fromDom, reply_to: replyTo, claimed_iban: claimed, domain_distance: (exact || sub) ? 0 : best, register_size: reg.length, deterministic_score: Math.min(score, 100), signal_count: signals.length, signals: signals, subject: clip(f.subject, 300), email_body: clip(f.email_body, 6000), block_at: p.block_at, review_at: p.review_at } }];

