const s = $('Score Deterministic Fraud Signals').first().json;
const dns = $('Check Sender Domain MX Records').first().json || {};
const raw = $input.first().json || {};
const ai = raw.output ? raw.output : raw;
const signals = s.signals.slice();
let score = s.deterministic_score;
const answers = Array.isArray(dns.Answer) ? dns.Answer.length : 0;
if(answers === 0 && s.domain_distance !== 0){ score = score + 15; signals.push({ weight: 15, code: 'NO_MX_RECORDS', detail: 'The sender domain ' + (s.from_domain || 'supplied') + ' publishes no MX records, so it cannot receive mail. Throwaway domains registered for a single fraud attempt often look like this.' }); }
const pressure = Number(ai.pressure_score || 0);
const tactics = Array.isArray(ai.tactics) ? ai.tactics.slice(0, 8).map(t => String(t).slice(0, 40)) : [];
if(pressure > 0){ const w = Math.round(Math.min(pressure, 100) * 0.2); score = score + w; signals.push({ weight: w, code: 'PRESSURE_LANGUAGE', detail: 'Language analysis scored ' + Math.min(pressure, 100) + ' out of 100 for pressure tactics: ' + (tactics.length ? tactics.join(', ') : 'none named') }); }
score = Math.min(score, 100);
const band = score >= s.block_at ? 'BLOCK' : (score >= s.review_at ? 'REVIEW' : 'PASS');
const ordered = signals.sort((a,b) => b.weight - a.weight);
const lines = ordered.map(x => '[' + x.weight + '] ' + x.code + ': ' + x.detail);
const codes = ordered.map(x => x.code).join(', ');
const vendorLabel = s.vendor_matched || 'an unrecognised sender';
const action = band === 'BLOCK' ? 'DO NOT PAY. Verify with ' + vendorLabel + ' by calling the number already held on file (' + (s.callback_phone || 'no number on file, find one from your own records') + '). Never use a phone number printed in the email itself.' : (band === 'REVIEW' ? 'Hold the payment and verify by callback to a number from your own records before releasing any funds.' : 'No fraud indicators above threshold. Your normal approval process applies.');
return [{ json: { risk_band: band, risk_score: score, vendor_matched: s.vendor_matched, from_address: s.from_address, claimed_iban: s.claimed_iban, known_iban_last4: s.known_iban_last4, callback_phone: s.callback_phone, register_size: s.register_size, pressure_score: pressure, tactics: tactics, signal_codes: codes, signals: ordered, recommended_action: action, checked_at: new Date().toISOString(), report: lines.join('\n') } }];

